findings.existing_code:
task_signals:
  type: object
  required: [archetype]
  properties:
    archetype: {type: string, minLength: 1}
    phase: {type: [string, "null"], default: null}
    task_type: {type: [string, "null"], default: null}
    complexity: {type: [string, "null"], enum: [low, medium, high, null]}
    modality: {type: string, enum: [interactive, programmatic], default: programmatic}
  additionalProperties: true
